mapper.select:
select trim(a.community_name) as community_name, count(1) as address_count, sum(case when nullif(trim(a.target_type), '') is not null or nullif(trim(a.target_name), '') is not null then 1 else 0 end) as device_count, count(distinct a.network_id) as network_count, sum(case when a.status = 'ALLOCATED' then 1 else 0 end) as allocated_count, sum(case when a.status = 'ISSUED' then 1 else 0 end) as issued_count, substring_index(group_concat(a.ip_address order by a.ip_value separator ','), ',', 1) as first_ip, substring_index(group_concat(a.ip_address order by a.ip_value desc separator ','), ',', 1) as last_ip, group_concat(distinct nullif(trim(n.network_name), '') order by n.start_value separator '、') as network_name_summary, group_concat(distinct nullif(trim(n.police_station_name), '') order by n.police_station_name separator '、') as police_station_summary, group_concat(distinct nullif(trim(a.internal_ip_address), '') order by a.internal_ip_address separator '、') as internal_ip_summary, group_concat(distinct nullif(trim(a.target_type), '') order by a.target_type separator '、') as target_type_summary, group_concat(distinct nullif(trim(a.manufacturer), '') order by a.manufacturer separator '、') as manufacturer_summary, group_concat(distinct nullif(trim(a.access_unit), '') order by a.access_unit separator '、') as access_unit_summary, group_concat(distinct nullif(trim(a.owner_name), '') order by a.owner_name separator '、') as owner_summary, group_concat(distinct nullif(trim(concat_ws(' ', a.mapping_address, a.mapping_port, a.mapping_description)), '') order by a.mapping_address separator '、') as mapping_summary from ipam_address a left join ipam_network n on n.network_id = a.network_id where a.status in ('ALLOCATED', 'ISSUED') and nullif(trim(a.community_name), '') is not null
and trim(n.police_station_name) = #{policeStationName}
group by trim(a.community_name) order by min(a.ip_value)

select ifnull(nullif(trim(a.target_type), ''), '未填写') as name, count(1) as value from ipam_address a left join ipam_network n on n.network_id = a.network_id where a.status in ('ALLOCATED', 'ISSUED')
and trim(n.police_station_name) = #{policeStationName}
group by ifnull(nullif(trim(a.target_type), ''), '未填写') order by value desc, name

select ifnull(nullif(trim(a.manufacturer), ''), '未填写') as name, count(1) as value from ipam_address a left join ipam_network n on n.network_id = a.network_id where a.status in ('ALLOCATED', 'ISSUED')
and trim(n.police_station_name) = #{policeStationName}
group by ifnull(nullif(trim(a.manufacturer), ''), '未填写') order by value desc, name
